@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Course Catalog</h1>

    <form method="get" action="/courses" class="row g-3 mb-4">
        <div class="col-md-6">
            <label for="search" class="form-label">Search</label>
            <input type="text" class="form-control" id="search" name="search"
                   value="@Search" placeholder="Search by title, code, or instructor..." />
        </div>
        <div class="col-md-4">
            <label for="departmentId" class="form-label">Department</label>
            <select class="form-select" id="departmentId" name="departmentId">
                <option value="">All Departments</option>
                @foreach (var dept in Departments)
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2 d-flex align-items-end">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @if (Courses.Count == 0)
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in Courses)
                    {
                        <tr>
                            <td><strong>@course.CourseCode</strong></td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @Courses.Count course(s)</p>
    }
</div>

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<UniversityCourseCatalog.Models.Course> Courses { get; set; } = [];
    private List<UniversityCourseCatalog.Models.Department> Departments { get; set; } = [];

    protected override void OnInitialized()
    {
        Departments = CatalogService.GetDepartments();
        Courses = CatalogService.GetCourses(Search, DepartmentId);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (Submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
                <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
            <hr />
            <p class="mb-0">You will receive a confirmation via your university email within 2 business days.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Back to Catalog</a>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <form method="post" action="/enroll">
                    <AntiforgeryToken />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <input type="text" class="form-control" id="fullName" name="Model.FullName"
                               value="@Model.FullName" required />
                        <ValidationMessage For="() => Model.FullName" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                               value="@Model.StudentId" placeholder="e.g., CS123456" required />
                        <ValidationMessage For="() => Model.StudentId" />
                        <div class="form-text">Format: 2 uppercase letters followed by 6 digits.</div>
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <select class="form-select" id="courseId" name="Model.CourseId" required>
                            <option value="0">-- Select a course --</option>
                            @foreach (var course in Courses)
                            {
                                <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                                    @course.CourseCode — @course.Title (@course.Credits cr)
                                </option>
                            }
                        </select>
                        <ValidationMessage For="() => Model.CourseId" />
                    </div>

                    <button type="submit" class="btn btn-success btn-lg">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary btn-lg ms-2">Cancel</a>
                </form>
            </div>

            <div class="col-lg-4">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5 class="card-title">How it works</h5>
                        <ol class="mb-0">
                            <li>Fill out the form with your details.</li>
                            <li>Select the course you wish to enroll in.</li>
                            <li>Submit your request.</li>
                            <li>Receive confirmation via email within 2 business days.</li>
                        </ol>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm] public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private bool Submitted { get; set; }
    private List<UniversityCourseCatalog.Models.Course> Courses { get; set; } = [];

    protected override void OnInitialized()
    {
        Courses = CatalogService.GetCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }

        if (HttpMethods.IsPost(HttpContextAccessor.HttpContext?.Request.Method ?? "GET"))
        {
            Submitted = true;
        }
    }

    [CascadingParameter] public HttpContext? HttpContextAccessor { get; set; }
}

